// Pin `core.hooksPath` so the tracked `.husky/pre-commit` runs in every
// worktree (OP-110 follow-up; ADR-0310 §2).
//
// `core.hooksPath` is one value in the *shared* repo-local config. Git resolves
// a relative value against each worktree root, and husky's `prepare` step
// resets the key to the relative `.husky/_` on every install. A fresh
// `git worktree add` worktree carries the tracked `.husky/pre-commit` but has
// no `.husky/_` (its contents are git-ignored and only generated by an
// install), so with husky's default no hook fires there at all — the commit
// that a worker makes first. The tracked `.husky` directory, by contrast, exists
// in every worktree, so pointing the hooks path at it makes the hook run
// unconditionally, from the worktree's own copy of the file.
//
// Runs after `husky` in the `prepare` script; a no-op outside a git work tree,
// so it can never break an install.
import { execFileSync } from "node:child_process";

/** @param {readonly string[]} args */
function git(args) {
  return execFileSync("git", args, { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
}

try {
  git(["rev-parse", "--is-inside-work-tree"]);
  git(["config", "core.hooksPath", ".husky"]);
} catch {
  // No work tree to configure (e.g. an install from a source tarball).
}
